// dosagem, forma farmacêutica, laboratório e tipo.

export const MEDICINE_TYPES = {
  referencia: { label: 'Referência',  color: '#3b82f6', bg: 'rgba(59,130,246,.15)',  short: 'REF' },
  generico:   { label: 'Genérico',    color: '#22c55e', bg: 'rgba(34,197,94,.15)',   short: 'GEN' },
  similar:    { label: 'Similar',     color: '#f59e0b', bg: 'rgba(245,158,11,.15)',  short: 'SIM' },
  outro:      { label: 'Personaliz.', color: '#8b5cf6', bg: 'rgba(139,92,246,.15)',  short: 'PER' },
};

// id auto-incrementado apenas para referência local
let _id = 1;
const mk = (commercial_name, active_ingredient, dosage, pharmaceutical_form, unit, manufacturer, medicine_type) => ({
  id: String(_id++),
  commercial_name,
  active_ingredient,
  dosage,
  pharmaceutical_form,
  unit,
  manufacturer,
  medicine_type,
  is_reference: medicine_type === 'referencia',
  is_generic:   medicine_type === 'generico',
  is_similar:   medicine_type === 'similar',
  is_custom:    false,
});

